arguments.command:
python -c 'from report import report_time
cases = {
    "2024-01-02T03:04:05+08:00": "2024-01-01 19:04:05 UTC",
    "2024-01-01T19:04:05Z": "2024-01-01 19:04:05 UTC",
    "2024-01-02T03:04:05.987654-05:30": "2024-01-02 08:34:05 UTC",
}
for source, expected in cases.items():
    actual = report_time(source)
    assert actual == expected, (source, actual, expected)
try:
    report_time("2024-01-02T03:04:05")
except ValueError:
    pass
else:
    raise AssertionError("naive timestamp was accepted")
print("report_time checks passed")' && python -m py_compile report.py

